// === Tab: mySketch ===
let particles = [];
let flashDuration = 200; // 強光持續時間，單位為毫秒
let lastFlashTime = 0; // 記錄上一次強光的時間

class Particle {
  constructor(x, y) {
    this.pos = createVector(x, y);
    this.vel = p5.Vector.random2D().mult(random(2, 5));
    this.acc = createVector();
    this.lifespan = 255;
    this.size = random(3, 10);
    this.isProton = random() > 0.5;
    this.color = this.isProton ? color(255, 100, 100) : color(100, 100, 255);
  }

  applyForce(force) {
    this.acc.add(force);
  }

  update() {
    this.vel.add(this.acc);
    this.pos.add(this.vel);
    this.acc.mult(0);

    // 邊界檢測，使中子粒子在碰到邊框時反彈
    if (this.isProton) {
      if (this.pos.x < 0 || this.pos.x > width) {
        this.vel.x *= -1;
      }
      if (this.pos.y < 0 || this.pos.y > height) {
        this.vel.y *= -1;
      }
    }

    this.lifespan -= 2;
  }

  show() {
    fill(this.color, this.lifespan);
    ellipse(this.pos.x, this.pos.y, this.size);
  }

  isDead() {
    return this.lifespan <= 0;
  }
}

function setup() {
  createCanvas(windowWidth, windowHeight); // 
  background(0); // 
  noFill(); // 確保只繪製粒子而不形成連接線
}

function draw() {
  // 檢查是否超過強光的持續時間，如果是則繪製黑色背景
  if (millis() - lastFlashTime > flashDuration) {
    background(0);
  }


  particles = particles.filter(p => p instanceof Particle);

  for (let i = particles.length - 1; i >= 0; i--) {
    let p = particles[i];
    p.applyForce(p5.Vector.random2D().mult(0.1));

    p.update();
    p.show();

    if (p.isDead()) {
      particles.splice(i, 1);
    }
  }
}

function mousePressed() {

  lastFlashTime = millis();


  background(255);

  for (let i = 0; i < 100; i++) {
    var p = new Particle((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
    particles.push(p);
  }

  frameRate(60);
}

